import{c as e,Q as t,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"MetaGPT: Meta Programming for A Multi-Agent Collaborative Framework","description":"","frontmatter":{"url":"https://arxiv.org/abs/2308.00352","title":"MetaGPT: Meta Programming for A Multi-Agent Collaborative Framework","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2308.00352,"authors":["Sirui Hong","Mingchen Zhuge","Jonathan Chen","Xiawu Zheng","Yuheng Cheng","Ceyao Zhang","Jinlin Wang","Zili Wang","Steven Ka Shing Yau","Zijuan Lin","Liyang Zhou","Chenyu Ran","Lingfeng Xiao","Chenglin Wu","Jürgen Schmidhuber"],"domains":["cs.AI","cs.MA"],"pdf_path":"pdfs/2308.00352.pdf","published_date":"2023-08-01T00:00:00.000Z","tags":["multi-agent","sop","software-development","meta-programming","role-based","llm"],"venue":"ICLR 2024"},"headers":[],"relativePath":"research/papers/2023-08-01-metagpt-multi-agent-collaborative-framework-2308-00352.md","filePath":"research/papers/2023-08-01-metagpt-multi-agent-collaborative-framework-2308-00352.md","lastUpdated":1785909234000}'),n={name:"research/papers/2023-08-01-metagpt-multi-agent-collaborative-framework-2308-00352.md"};function i(l,a,s,g,m,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="metagpt-meta-programming-for-a-multi-agent-collaborative-framework" tabindex="-1">MetaGPT: Meta Programming for A Multi-Agent Collaborative Framework <a class="header-anchor" href="#metagpt-meta-programming-for-a-multi-agent-collaborative-framework" aria-label="Permalink to &quot;MetaGPT: Meta Programming for A Multi-Agent Collaborative Framework&quot;">​</a></h1><p><strong>arXiv</strong>: 2308.00352 | <strong>發表</strong>: 2023-08-01 | <strong>PDF</strong>: 2023-08-01-metagpt-multi-agent-collaborative-framework-2308-00352.pdf</p><h2 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h2><p>將人類軟體工程 Standardized Operating Procedures（SOP）編碼進 LLM multi-agent 工作流。每個 agent 扮演具體職能角色（Product Manager / Architect / Project Manager / Engineer / QA），以結構化文件（需求文件、設計圖、API 規範）取代非結構化對話傳遞，防止級聯幻覺（cascading hallucination）。</p><h2 id="方法-架構" tabindex="-1">方法 / 架構 <a class="header-anchor" href="#方法-架構" aria-label="Permalink to &quot;方法 / 架構&quot;">​</a></h2><ul><li><strong>角色分工（Role Specialization）</strong>：5 個固定角色，各有明確職責邊界；不跨角色自決</li><li><strong>結構化輸出（Structured Communication）</strong>：agent 輸出 diagrams / documents 而非自由文字，強制中間驗證</li><li><strong>可執行回饋迴圈（Executable Feedback）</strong>：Engineer 可迭代測試 + debug；QA 驗證後回饋修正</li></ul><h2 id="關鍵發現與數據" tabindex="-1">關鍵發現與數據 <a class="header-anchor" href="#關鍵發現與數據" aria-label="Permalink to &quot;關鍵發現與數據&quot;">​</a></h2><ul><li>HumanEval Pass@1：<strong>85.9%</strong>；MBPP Pass@1：<strong>87.7%</strong>（當時 SOTA）</li><li>SoftwareDev executability score：<strong>3.75 / 4</strong>；Human revision cost：<strong>0.83</strong> 次/任務</li><li>Token 效率：<strong>124.3 tokens/loc</strong>（vs. ChatDev 248.9，節省 50%）</li><li>AutoGPT / LangChain / AgentVerse 在 SoftwareDev 全部得分 1.0（無法生成可執行代碼）</li></ul><h2 id="對-agent-team-設計的啟示" tabindex="-1">對 agent-team 設計的啟示 <a class="header-anchor" href="#對-agent-team-設計的啟示" aria-label="Permalink to &quot;對 agent-team 設計的啟示&quot;">​</a></h2><ol><li><strong>SOP 即 coordination protocol</strong>：人類組織流程可直接轉為 prompt sequence，大幅減少 agent 間歧義</li><li><strong>結構化 artifacts &gt; 自由對話</strong>：強制中間產出格式讓 agent 協作可機械驗證（R4 完成條件思想）</li><li><strong>角色邊界保護 token 效率</strong>：避免多 agent 重複做同一件事，token 節省 2× 可觀</li></ol><h2 id="原文關鍵引用-≤150字" tabindex="-1">原文關鍵引用（≤150字） <a class="header-anchor" href="#原文關鍵引用-≤150字" aria-label="Permalink to &quot;原文關鍵引用（≤150字）&quot;">​</a></h2><blockquote><p>&quot;MetaGPT incorporates efficient human workflows as a meta programming approach into LLM-based multi-agent collaboration. Specifically, MetaGPT encodes Standardized Operating Procedures (SOPs) into prompt sequences for more streamlined workflows, thus allowing agents with human-like domain expertise to verify intermediate results and reduce errors. MetaGPT takes a multi-agent framework built on top of GPT-4 and assigns different roles to GPT-4 agents to collaboratively complete complex software engineering tasks.&quot;</p></blockquote>',12)])])}const h=e(n,[["render",i]]);export{d as __pageData,h as default};
